mapper.update:
UPDATE user_profiles up
JOIN user_gym ug ON ug.user_id = up.user_id AND ug.gym_id = #{gymId} AND ug.is_active = 1
SET up.name=#{staff.name}, up.contact=#{staff.phone}
WHERE up.user_id=#{staff.id};
UPDATE users u
JOIN user_gym ug ON ug.user_id = u.user_id AND ug.gym_id = #{gymId} AND ug.is_active = 1
SET u.email=#{staff.email}
WHERE u.user_id=#{staff.id}
